mapper.select:
SELECT * FROM stock_daily
WHERE stock_code = #{stockCode}
  AND YEAR(trade_date) = #{year}
ORDER BY trade_date ASC
LIMIT 1

SELECT * FROM stock_daily
WHERE stock_code = #{stockCode}
  AND YEAR(trade_date) = #{year}
ORDER BY trade_date DESC
LIMIT 1

SELECT * FROM stock_daily
WHERE stock_code = #{stockCode}
  AND trade_date BETWEEN #{startDate} AND #{endDate}
ORDER BY trade_date ASC

SELECT eff.stock_code AS stockCode, s.stock_name AS stockName, s.industry, eff.close_price AS price, eff.eff_cp AS changePct, eff.volume FROM ( SELECT d.stock_code, d.close_price, d.volume, CASE WHEN d.change_percent IS NOT NULL AND d.change_percent != 0 THEN d.change_percent ELSE ROUND((d.close_price - COALESCE(y.close_price, d.pre_close, 0)) / GREATEST(COALESCE(y.close_price, d.pre_close, 0.01), 0.01) * 100, 4) END AS eff_cp FROM stock_daily d LEFT JOIN stock_daily y ON d.stock_code = y.stock_code AND y.trade_date = DATE_SUB(d.trade_date, INTERVAL 1 DAY) WHERE d.trade_date = (SELECT MAX(trade_date) FROM stock_daily) AND d.close_price IS NOT NULL ) eff JOIN stock s ON eff.stock_code = s.stock_code
WHERE s.industry LIKE CONCAT(#{industry}, '%')
AND eff.close_price >= #{minPrice}
AND eff.close_price <= #{maxPrice}
AND eff.eff_cp >= #{minChange}
ORDER BY eff.eff_cp DESC LIMIT #{limit}
